/** Percentile rank (0..100) of |v| within the body's long-term distribution.
 * @param {number} bodyId 0..9
 * @param {number} absV |speed| in deg/day
 * @returns {number} */
export function speedPercentile(bodyId, absV) {
  const st = SPEED_STATS[bodyId];
  if (!st || !Number.isFinite(absV)) return NaN;
  const q = st.q;
  if (absV <= q[0]) return 0;
  if (absV >= q[100]) return 100;
  let lo = 0, hi = 100;
  while (hi - lo > 1) { const mid = (lo + hi) >> 1; if (q[mid] <= absV) lo = mid; else hi = mid; }
  const span = q[hi] - q[lo];
  return lo + (span > 0 ? (absV - q[lo]) / span : 0);
}

/** z-score of |v| against the long-term mean/std. @returns {number} */
export function speedZ(bodyId, absV) {
  const st = SPEED_STATS[bodyId];
  if (!st || !Number.isFinite(absV) || st.std <= 0) return NaN;
  return (absV - st.mean) / st.std;
}

// Red (minima, percentile 0) -> yellow -> green (maxima, percentile 100).
// Two-segment lerp so the midpoint is yellow, not muddy brown.
const C_RED = [248, 81, 73], C_YELLOW = [210, 153, 34], C_GREEN = [63, 185, 80];
/** CSS color for a speed percentile. @param {number} pct 0..100 @returns {string} */
export function speedColor(pct) {
  const t = Math.min(100, Math.max(0, pct)) / 100;
  const a = t < 0.5 ? C_RED : C_YELLOW, b = t < 0.5 ? C_YELLOW : C_GREEN;
  const u = t < 0.5 ? t * 2 : (t - 0.5) * 2;
  const c = a.map((x, i) => Math.round(x + (b[i] - x) * u));
  return `rgb(${c[0]},${c[1]},${c[2]})`;
}
